def compute(vars):
    parent_value = vars["Ending Current Assets"]
    x1 = vars["Current Liabilities"]

    if parent_value is None or x1 is None:
        return {
            "value": None,
            "trace": {
                "Ending Current Assets": parent_value,
                "Current Liabilities": x1,
                "output_meta": {
                    "currency": None,
                    "scale": "ones",
                    "unit": "ratio"
                }
            }
        }

    if x1 == 0:
        return None

    current_ratio = parent_value / x1

    return {
        "value": current_ratio,
        "trace": {
            "Ending Current Assets": parent_value,
            "Current Liabilities": x1,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
